<script setup>
import NativeReports from '../components/NativeReports.vue'
import { computed, onMounted, ref } from 'vue'
import { apiGet } from '../api'
import { exportUrl, recordRoute } from '../discovery'
const catalogue = ref([]), query = ref(''), selected = ref(null), filters = ref([]), columns = ref([]), rows = ref([]), more = ref(false), busy = ref(false), error = ref(''), loaded = ref(false)
const matches = computed(() => catalogue.value.filter(r => `${r.title} ${r.module}`.toLowerCase().includes(query.value.toLowerCase())))
let generation = 0
function choose(report) { generation++; busy.value = false; selected.value = report; columns.value = report.columns.slice(0,8).map(c=>c.fieldname); filters.value = []; rows.value = []; loaded.value = false; more.value = false; error.value = '' }
async function run(append = false) {
 const id = ++generation; busy.value = true; error.value = ''
 try { const result = (await apiGet('/api/method/sidra_realestate.api.discovery.report', { doctype: selected.value.doctype, filters: filters.value, columns: columns.value, start: append ? rows.value.length : 0 })).message; if (id === generation) { rows.value = append ? [...rows.value,...result.rows] : result.rows; more.value = result.has_more; loaded.value = true } }
 catch(e) { if (id === generation) error.value = e.message } finally { if (id === generation) busy.value = false }
}
function changed() { generation++; busy.value = false; rows.value = []; more.value = false; loaded.value = false }
onMounted(async()=>{ try { catalogue.value = (await apiGet('/api/method/sidra_realestate.api.discovery.catalogue')).message } catch(e) { error.value = e.message } })
</script>
<template><section class="page"><h1 class="page__title">Report catalogue</h1><p>Operational record reports across your permitted modules. Exports include all matching rows, up to 10,000.</p><label>Find a report<input v-model="query" class="bj-input" type="search" /></label><NativeReports :search="query" /><h2>Operational reports</h2><div class="catalogue"><button v-for="r in matches" :key="r.doctype" class="bj-btn" :aria-pressed="selected?.doctype === r.doctype" @click="choose(r)">{{ r.title }}</button></div><p v-if="!catalogue.length && !error">No operational reports are available to your role.</p><p v-if="error" role="alert">{{ error }}</p><section v-if="selected" class="bj-card"><h2>{{ selected.title }}</h2><details><summary>Columns</summary><label v-for="c in selected.columns" :key="c.fieldname" class="column"><input v-model="columns" type="checkbox" :value="c.fieldname" @change="changed" />{{ c.label }}</label></details><div v-for="(f,i) in filters" :key="i" class="filter"><select v-model="f[0]" class="bj-input" aria-label="Filter field" @change="changed"><option v-for="c in selected.columns" :key="c.fieldname" :value="c.fieldname">{{ c.label }}</option></select><select v-model="f[1]" class="bj-input" aria-label="Filter operator" @change="changed"><option v-for="op in ['=','!=','like','>=','<=']" :key="op">{{op}}</option></select><input v-model="f[2]" class="bj-input" aria-label="Filter value" @input="changed" /><button class="bj-btn" @click="filters.splice(i,1); changed()">Remove</button></div><p class="bj-muted">Use % as a wildcard with “like”. Dates use YYYY-MM-DD.</p><div class="actions"><button class="bj-btn" @click="filters.push(['name','=','']); changed()">Add filter</button><button class="bj-btn" :disabled="busy || !columns.length" @click="run()">Run report</button><a v-if="selected.can_export && loaded" class="bj-btn" :href="exportUrl(selected.doctype,filters,columns)">Export matching rows (CSV)</a></div><div class="table"><table v-if="loaded"><thead><tr><th v-for="c in columns" :key="c">{{ selected.columns.find(f=>f.fieldname===c)?.label }}</th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="i"><td v-for="c in columns" :key="c"><RouterLink v-if="selected.columns.find(f=>f.fieldname===c)?.fieldtype === 'Link' && row[c] && recordRoute(selected.columns.find(f=>f.fieldname===c)?.options,row[c])" :to="recordRoute(selected.columns.find(f=>f.fieldname===c)?.options,row[c])">{{ row[c] }}</RouterLink><span v-else>{{ row[c] ?? '—' }}</span></td></tr></tbody></table></div><p v-if="loaded && !rows.length">No matching records.</p><button v-if="more" class="bj-btn" :disabled="busy" @click="run(true)">Load more</button><p v-if="busy" role="status">Loading…</p></section></section></template>
<style scoped>h1 { margin-bottom:12px } h2 { margin:20px 0 12px;font-size:17px;font-weight:600 }.catalogue,.actions { display:flex;gap:8px;flex-wrap:wrap;margin:16px 0 }.filter { display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 }.filter>* { flex:1;min-width:100px }.column { display:inline-flex;gap:8px;margin:8px }.table { overflow:auto } table { border-collapse:collapse;width:100% } td,th { text-align:left;padding:12px;border-bottom:1px solid var(--bj-line);white-space:nowrap } label { display:block } summary { min-height:44px;cursor:pointer }</style>
